import math


def evaluate(expr: str) -> int:
    # 1. Tokenize input string
    raw_tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            raw_tokens.append(('NUM', int(expr[start:i])))
        elif c in '+-*/%^!()':
            raw_tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # 2. Validate token adjacency and insert implicit multiplication
    tokens = []
    for tok in raw_tokens:
        if tokens:
            prev = tokens[-1]
            if prev[0] == 'NUM' and tok[0] == 'NUM':
                raise ValueError("Malformed expression: adjacent numbers separated by whitespace")
            if prev[0] == ')' and tok[0] == 'NUM':
                raise ValueError("Malformed expression: number directly after closing parenthesis")
            if prev[0] in ('NUM', ')', '!') and tok[0] == '(':
                tokens.append(('*', '*'))
        tokens.append(tok)

    if not tokens:
        raise ValueError("Empty expression")

    # 3. Arithmetic helper functions
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Division by zero")
        res = abs(a) // abs(b)
        return -res if (a < 0) ^ (b < 0) else res

    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Remainder by zero")
        rem = abs(a) % abs(b)
        return -rem if a < 0 else rem

    def power(base: int, exp: int) -> int:
        if exp < 0:
            raise ValueError("Negative exponent")
        return base ** exp

    def factorial(n: int) -> int:
        if n < 0:
            raise ValueError("Factorial of negative number")
        return math.factorial(n)

    # 4. Recursive descent parser
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return ('EOF', '')

    def consume(expected=None):
        nonlocal pos
        tok = peek()
        if expected is not None and tok[0] != expected:
            raise ValueError(f"Expected {expected}, got {tok[0]}")
        if tok[0] == 'EOF':
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tok

    def parse_expr() -> int:
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                val = val + right
            else:
                val = val - right
        return val

    def parse_term() -> int:
        val = parse_unary()
        while peek()[0] in ('*', '/', '%'):
            op = consume()[0]
            right = parse_unary()
            if op == '*':
                val = val * right
            elif op == '/':
                val = trunc_div(val, right)
            elif op == '%':
                val = trunc_mod(val, right)
        return val

    def parse_unary() -> int:
        neg_count = 0
        while peek()[0] == '-':
            consume('-')
            neg_count += 1
        val = parse_power()
        return -val if neg_count % 2 == 1 else val

    def parse_power() -> int:
        val = parse_postfix()
        if peek()[0] == '^':
            consume('^')
            exp = parse_unary()
            val = power(val, exp)
        return val

    def parse_postfix() -> int:
        val = parse_primary()
        while peek()[0] == '!':
            consume('!')
            val = factorial(val)
        return val

    def parse_primary() -> int:
        tok = peek()
        if tok[0] == 'NUM':
            consume('NUM')
            return tok[1]
        elif tok[0] == '(':
            consume('(')
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Expected ')'")
            consume(')')
            return val
        else:
            raise ValueError(f"Unexpected token: {tok[0]}")

    result = parse_expr()
    if peek()[0] != 'EOF':
        raise ValueError(f"Unexpected trailing token: {peek()[0]}")
    return result
